// Keep only creators not yet in the sheet, each with a way to reach them. One row per creator, ready for outreach.
const existing = new Set($input.all().map((i) => i.json.channelUrl).filter(Boolean));
const rows = $('Find the creators this audience watches').all().map((i) => i.json).filter((r) => r.channelUrl);
const today = new Date().toISOString().slice(0, 10);
return rows
  .filter((r) => !existing.has(r.channelUrl) && r.bestContact)
  .map((r) => ({ json: {
    foundOn: today, rank: r.rank, tier: r.tier, platform: r.platform, channelName: r.channelName, channelUrl: r.channelUrl,
    subscribers: r.channelSubscribers, fit: r.fit, whyItFits: r.whyItFits, country: r.country || r.channelCountry || '',
    bestContact: r.bestContact, contactSource: r.contactSource, sampleVideo: (r.sampleVideoUrls || [])[0] || '', status: 'to contact',
  } }));
